'use strict';
const main=document.querySelector('main');
const A='assets/';
const state={uploads:{},urls:{},scroll:'xihu'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset=(key,fallback)=>state.urls[key]||(fallback?A+fallback:'');
const icons={
 resume:`<svg viewBox="0 0 160 80" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path fill="#fff9e9" d="m29 14 72-4 3 60-73 4z"/><path fill="#fffdf7" d="m44 7 72 4-3 60-73-4z"/><path d="m55 23 34 2m-34 10 45 2m-46 10 31 2m-32 10 39 2"/><path d="m115 47 16-24 7 5-16 24-11 6z"/><path d="m129 26 7 5m-22 17 7 5"/><path d="m16 18 3-7 3 7 7 3-7 3-3 7-3-7-7-3z"/></svg>`,
 code:`<svg viewBox="0 0 160 80" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path fill="#fafcf9" d="m29 15 92 1 3 52-94-1z"/><path d="m19 68 117 1-9 7-97-1zM39 24h74v34H39z"/><path d="m59 35-8 7 8 6m33-13 8 7-8 7m-19-17-6 21"/><path d="m126 10 5-7m3 16 10-3m-3 14 9 4"/></svg>`,
 aigc:`<svg viewBox="0 0 160 80" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path fill="#fff8f6" d="m27 17 78-8 6 57-77 9z"/><path d="m37 54 17-21 13 11 15-23 17 29M44 27a5 5 0 1 0 0-.1z"/><path fill="#f1d99c" d="m95 61 24-38 8 5-24 38-12 6z"/><path d="m116 27 9 5m-29 29 7 5M124 10v10m-5-5h10m8 27v12m-6-6h12"/></svg>`,
 book:`<svg viewBox="0 0 160 90" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path fill="#fffdf9" d="M26 21c15-6 32-2 47 7 16-9 33-11 53-5l-5 51c-16-5-33-3-48 4-16-8-31-11-49-6z"/><path d="M73 28v50M33 33c11-2 21 0 31 5m-32 5c11-2 21 0 31 5m-32 5c11-2 21 0 31 5m22-20c12-6 22-7 32-5m-32 15c12-6 22-7 32-5m-32 15c12-6 22-7 32-5"/><path d="m129 10 4-7 3 7 8 3-8 3-3 8-4-8-7-3z"/></svg>`
};
function breadcrumb(items=[]){return `<div class="breadcrumb"><a href="#home">← 返回首页</a>${items.map(([label,href])=>`<span>/</span>${href?`<a href="${href}">${esc(label)}</a>`:`<span>${esc(label)}</span>`}`).join('')}</div>`;}
function heading(en,title,desc,note=''){return `<div class="page-heading"><div><span class="eyebrow">${en}</span><h1>${title}</h1><p>${desc}</p></div>${note?`<span class="corner-note">${note}</span>`:''}</div>`;}
function tags(items){return `<div class="tags">${items.map(s=>`<span class="tag">${s}</span>`).join('')}</div>`;}
function figure(src,title,caption='',cls=''){return `<figure class="figure ${cls}"><img src="${esc(src)}" alt="${esc(title)}" loading="lazy"><figcaption><strong>${title}</strong>${caption}</figcaption></figure>`;}
function flow(items){return `<div class="flow">${items.map((s,i)=>`${i?'<i aria-hidden="true">→</i>':''}<span>${s}</span>`).join('')}</div>`;}
function timeline(items,label){return `<div class="timeline-wrap" aria-label="${label}"><ol class="plain-timeline">${items.map(x=>`<li class="${x.featured?'timeline-featured':''}"><div class="timeline-name">${x.jump?`<a href="#internships" data-jump="${x.jump}">${x.name}</a>`:x.name}<span>${x.desc}</span></div><span class="timeline-dot" aria-hidden="true"></span><time>${x.time}</time></li>`).join('')}</ol></div>`;}
function educationTimeline(){return timeline([{name:'东华大学',desc:'工业设计 · 本科',time:'2019.09 — 2024.06'},{name:'浙江大学',desc:'工业设计工程 · 硕士（保研）',time:'2024.09 — 2027.06',featured:true},{name:'米兰理工大学',desc:'浙大硕士期间 · 半年交换',time:'2025.09 — 2026.02'}],'教育背景时间轴');}
function designHub(){return `${breadcrumb([['设计项目']])}${heading('','设计项目','从生成式视觉探索，到软硬件系统设计。')}<div class="design-entries"><a class="design-entry" href="#aigc/scroll"><img src="scrolls/xihu/assets/scroll.png" alt="风格化长卷预览"><div><h2>风格化长卷浏览 <span>↗</span></h2><p>西湖、浙大、宁波，静态长卷与动态漫游。</p></div></a><a class="design-entry" href="#aigc/ecommerce"><img src="assets/figurine-out.png" alt="AIGC 立体表达尝试"><div><h2>其他 AIGC 尝试 <span>↗</span></h2><p>电商生图、手绘与立体表达。</p></div></a><a class="design-entry design-entry-book" href="#design/portfolio"><div class="book-preview" aria-hidden="true">${icons.book}</div><div><h2>软硬件系统设计作品集 <span>↗</span></h2><p>2023 年保研期间的设计探索，在线翻阅完整 PDF。</p></div></a></div>`;}
function home(){return `<section class="digital-self"><div class="self-hero"><section class="self-intro"><h1>你好，<br>我是 Shilu。</h1><p class="self-statement">真实的我，<br>数字的表达。</p><p class="self-description">一个可以感知、回应、<br>与你互动的虚拟形象。</p><button class="button" type="button" data-self-chat>和 Shilu 聊聊 ↗</button></section><div class="self-character" aria-label="Shilu 的数字分身"><div class="self-character-surface" aria-hidden="true"></div><div class="self-character-motion"><img src="${asset('portrait','shilu-avatar-white.png')}" alt="Shilu 的白色数字分身形象" draggable="false"></div></div><aside class="self-info" aria-label="Shilu 个人信息"><h2>Shilu</h2><p class="self-info-sub">我的数字分身</p><dl><div><dt>教育背景</dt><dd>浙江大学 ｜ 软件学院 ｜ 工业设计工程</dd></div><div><dt>专注方向</dt><dd>AI 产品 ｜ 人机交互 ｜ 用户体验</dd></div><div><dt>创作方式</dt><dd>Vibe Coding ｜ ComfyUI ｜ 交互原型</dd></div></dl></aside></div><section class="self-chat-area avatar-conversation" aria-label="与 Shilu 的数字分身对话"><div class="avatar-chat" id="avatar-chat" role="log" aria-live="polite" aria-label="对话记录"><div class="avatar-message assistant"><p>我是 Shilu，很高兴在这里遇见你。</p></div></div><div class="avatar-prompts" aria-label="试着问问"><button type="button" data-avatar-question="你有几段实习？">你有几段实习？</button><button type="button" data-avatar-question="你的科研方向是什么？">你的科研方向是什么？</button><button type="button" data-avatar-question="你的兴趣爱好是什么？">你的兴趣爱好是什么？</button></div><form id="avatar-form" class="avatar-form"><label class="sr-only" for="avatar-input">与 Shilu 对话</label><textarea id="avatar-input" name="question" maxlength="600" rows="1" placeholder="与 Shilu 说句话…" required></textarea><button type="submit" class="button primary" id="avatar-send" aria-label="发送消息">发送 ↑</button></form><p class="avatar-status" id="avatar-status" role="status"></p></section></section>`;}
function internships(){return `${breadcrumb([['产品实习']])}${heading('WORK EXPERIENCE','在真实业务里，把问题想具体。','三段产品实习，分别关注 AI 体验、用户增长与交易策略。','Notes from real work.')}<div class="intern-layout"><aside class="side-index" aria-label="实习目录"><strong>实习目录</strong>${INTERNSHIPS.map((x,i)=>`<a href="#internships" data-jump="intern-${i}">${x.company}</a>`).join('')}<span class="muted">2025 — 2026</span></aside><div>${INTERNSHIPS.map((x,i)=>`<article class="experience" id="intern-${i}"><div class="experience-top"><span class="company-mark ${x.color}">${x.mark}</span><div><h2>${x.company}</h2><span class="role">${x.role}</span></div><time>${x.time}</time></div><p class="experience-summary">${x.summary}</p>${x.items.map(([h,p])=>`<div class="resume-item"><h3>${h}</h3><p>${p}</p></div>`).join('')}${tags(x.tags)}</article>`).join('')}</div></div>`;}
function vibe(){return `${breadcrumb([['AI 项目']])}${heading('IDEAS INTO PRODUCTS','把想法，做成能使用的东西。','两个个人项目，记录从需求定义、规则设计到开发验证的完整过程。','Made with curiosity & Codex')}<div class="project-grid">${Object.entries(PROJECTS).map(([id,p])=>`<a href="#project/${id}" class="project-card"><div class="project-preview ${p.color}">${id==='hehao'?`<span class="scribble">A softer way<br>to say it.</span><img class="phone" src="${A+p.image}" alt="和好喵分享卡片示例"><img class="cat-small" src="${A}cat.webp" alt="" aria-hidden="true">`:`<img class="desktop" src="${A+p.image}" alt="衣柜设计师布局编辑界面">`}</div><div class="project-card-body"><span class="eyebrow">${p.en}</span><h2>${p.name}<span aria-hidden="true">↗</span></h2><p>${p.brief}</p>${tags(p.tags)}<div class="project-footer"><span>查看从 0 到 1 的过程</span><span>案例手记 →</span></div></div></a>`).join('')}</div>`;}
function project(id){const p=PROJECTS[id];if(!p)return notFound();const wardrobe=id==='wardrobe';return `${breadcrumb([['AI 项目','#vibe'],[p.name]])}<article class="ppt-case ${wardrobe?'wardrobe-case':'hehao-case'}"><header class="ppt-case-head"><div><h1>${p.name}</h1><p>${wardrobe?'把「我想怎么收纳」，变成「厂家能看懂的衣柜方案」。':'帮人把话说清楚，不替人判对错。'}</p></div><a class="button primary" href="${p.url}" target="_blank" rel="noopener">体验项目 ↗</a></header>${wardrobe?wardrobeStory():hehaoStory()}</article><div class="case-next"><a href="#vibe">← 项目目录</a><a href="#project/${wardrobe?'hehao':'wardrobe'}">${wardrobe?'和好喵':'衣柜设计师'} →</a></div>`;}
function wardrobeStory(){return `<section class="ppt-two-col"><div><section><h2>问题起点：我自己的搬家</h2><p>旧衣柜只有一层分隔：短衣下方空一大块，长衣挂不下，只好折叠。问题不在总容量，而在<strong>内部分区与衣物结构不匹配</strong>。</p></section><section><h2>产品定位：联系厂家之前</h2><p>把收纳习惯变成衣柜方案，再配齐收纳配件。用户说得出「长衣多」，却说不出「几列、每格多高」。</p></section><section><h2>核心流程：6 步闭环</h2><p>空间与外形 → 衣物需求 → 3 套起步布局 → 个性化微调 → 图纸交付 → 配件清单。</p><p><strong>预览、检查、图纸、配件共用同一份数据。</strong></p></section></div>${figure(A+'deck-shot_design.png','衣柜布局设计界面','')}</section><section class="ppt-two-col drawing"><div>${figure(A+'deck-shot_drawing.png','图纸交付界面','正 / 侧 / 俯视尺寸图，可导出 PDF、SVG。冲突会说明位置与数值；图纸用于厂家沟通。')}</div><div><section><h2>关键取舍</h2><ul><li>规则引擎：尺寸要可复现、可校验。</li><li>一份数据驱动预览、图纸与配件，冲突可定位到列。</li><li>一字型柜、纯前端、无账户与真实支付。</li></ul></section><section><h2>验证与下一步</h2><p>线上可访问，16 项自动测试通过。下一步邀请 5–8 人做任务测试，观察独立完成率与询价意愿；独立用户测试、商家试用与转化数据仍待验证。</p></section><section><h2>AI 切入点 <small>规划</small></h2><p>将「长衣多、不想叠衣」转为结构化需求，并生成厂家沟通摘要。AI 管理解与解释，规则管尺寸与校验。</p></section></div></section>`;}
function hehaoStory(){return `<p class="ppt-lead">AI 辅助沟通工具：把截图或文字里的冲突，整理成一封可编辑、可分享的表达卡片，给想道歉、解释误会或说明边界的人。</p><p class="ppt-role">我的角色：负责产品需求、取舍与验收标准；用 Codex 完成实现。</p><section><h2>从一段冲突，到一次表达</h2><ol class="ppt-flow">${[['输入与核对','截图或文字，读取后须用户确认'],['风险与目标','危险优先，再分清道歉 / 解释 / 边界'],['必要追问','只问会改变建议的事，最多 3 轮'],['生成表达','千问模型按场景与关系策略写'],['规则校验','不过关最多重写一次'],['确认与分享','用户编辑确认，接收者自主反馈']].map(([h,t])=>`<li><h3>${h}</h3><p>${t}</p></li>`).join('')}</ol></section><section class="ppt-judgments">${[['不做关系裁判','关系只影响措辞，不决定谁有责任，也不承诺和好率。'],['不确定就保留未知','“不知道”“可能”不当事实，截图识别结果须用户核对。'],['失败要看得见','校验不过只重写一次，仍不过就报失败。']].map(([h,t])=>`<div><h3>${h}</h3><p>${t}</p></div>`).join('')}</section><section class="ppt-quality"><h2>质量怎么管</h2><p>已建 50 条单轮 + 10 条多轮案例，按四层 12 项、0–3 分评测。</p><div class="ppt-rubric"><p><b>信息理解</b>事实忠实、说话人准确</p><p><b>策略路由</b>下一步、追问、停止时机</p><p><b>生成质量</b>具体、责任、行动、语言</p><p><b>安全边界</b>不越界、不施压、护隐私</p></div><p>编造事实、危险仍劝和、泄露隐私、逼对方回复，作为严重失败单列。</p><h2>一次真实 Bad Case 的定位</h2><dl class="ppt-badcase"><dt>现象</dt><dd>“朋友迟到 20 分钟”合成案例中，真实模型写出未经确认的“请你喝杯东西”“我保证准时”，原校验器放行。</dd><dt>定位</dt><dd>固定词表未能识别换一种说法的补偿行动。</dd><dt>修改</dt><dd>新增“未确认补偿行动”和“行为担保”规则，接入原有重写流程；校验器升 v5，评测口径升 v6。</dd><dt>复测</dt><dd>新增 2 项程序检查通过；真实模型完成小样本复测，尚未形成通过率。</dd></dl><div class="ppt-evidence"><p><b>已验证</b>122 项程序 / 模拟检查通过；真实文字生成已小样本跑通。</p><p><b>下一步</b>真实模型全量评测、截图识别、真实用户试用与跨设备分享。</p></div></section>`;}
const SCROLLS={xihu:{name:'西湖十景',fallback:'../scrolls/xihu/assets/scroll.png',key:'scroll-xihu',caption:'新西湖十景 · 冬日湖山长卷',url:'scrolls/xihu/'},zju:{name:'浙大校区',fallback:'../scrolls/zju/assets/scroll.png',key:'scroll-zju',caption:'浙大八大校区 · 校园长卷',url:'scrolls/zju/'},ningbo:{name:'宁波城区',fallback:'../scrolls/ningbo/assets/scroll.png',key:'scroll-ningbo',caption:'宁波十景 · 城市长卷',url:'scrolls/ningbo/'}};
function scrollStage(){const s=SCROLLS[state.scroll];return `<div class="scroll-tabs" role="tablist" aria-label="长卷主题">${Object.entries(SCROLLS).map(([id,x])=>`<button role="tab" aria-selected="${state.scroll===id}" data-scroll="${id}">${x.name}</button>`).join('')}</div><div class="scroll-stage"><div class="scroll-viewport" tabindex="0" aria-label="${s.name}长卷，使用触控板横向滚动或方向键浏览"><img src="${asset(s.key,s.fallback)}" alt="${s.caption}"></div><div class="scroll-caption"><span>${s.caption}</span><a class="button small scroll-dynamic" href="${s.url}" target="_blank" rel="noopener" aria-label="动态浏览${s.name}长卷，在新页面打开">动态浏览 ${s.name} ↗</a></div></div>`;}
function emptyAsset(key,title,desc){const src=asset(key);return src?figure(src,title,'自行上传的素材，保存在当前浏览器。'):`<div class="empty-asset"><span class="empty-symbol" aria-hidden="true">▧ +</span><strong>${title}</strong><p>${desc}</p><button class="button small" data-upload="${key}">上传${title}</button></div>`;}
function aigc(sub='scroll'){if(!['scroll','ecommerce','industrial'].includes(sub))sub='scroll';const body=sub==='scroll'?`<section class="aigc-section native-workflow"><p class="workflow-intro">从浙大校区、西湖十景到宁波城区，将不同来源的建筑与风景，拼成一幅风格连续的城市长卷。</p><div class="workflow-story"><section><div><h2>先把城市拼起来</h2><p>按面积、年代与游览动线安排地标，搜集经典机位并抠出主体。在 Photoshop 中排定位置，统一视角与地平线，再用仿制图章、模糊画笔与 WebUI 局部重绘处理接缝。</p></div><div class="workflow-pair">${figure(A+'scroll-workflow-deck/assets/material.jpg','搜集地标并抠出主体','')}${figure(A+'scroll-workflow-deck/assets/inpaint_mask.jpg','预拼接与局部重绘蒙版','')}</div></section><section class="workflow-core"><div><h2>让风格变化，保留建筑结构</h2><p>WD14 从参考图反推提示词，IPAdapter 在 SDXL 下迁移风格；ControlNet 通过深度与线稿双控，约束建筑轮廓和空间结构。</p><p>DreamShaper XL Turbo 经 K 采样器与 VAE 解码初次出图，再用 FLUX 去噪增强细节、ESRGAN 超分高清。</p><p class="workflow-parameters">采样步数 5–8。变形时加强 CN 控制，风格弱时调整权重，噪点则重新采样或更换参考图。</p></div><div class="workflow-controls">${figure(A+'scroll-workflow-deck/assets/style_ref.jpg','风格参考','')}${figure(A+'scroll-workflow-deck/assets/depth.jpg','DepthAnything 深度约束','')}${figure(A+'scroll-workflow-deck/assets/lineart.jpg','LineArt 线稿约束','')}</div></section><section><div><h2>最后，回到整幅画面</h2><p>在 PS 中衔接分段，用同一 LoRA 局部重绘接缝。对风格化后脱离特征的局部，单独生成并人工修复，让整幅长卷的色彩、地标与过渡保持连续。</p></div>${figure(A+'scroll-workflow-deck/assets/inpaint.jpg','接缝重绘与人工精修','')}</section></div><div class="workflow-comparison">${figure(A+'scroll-workflow-deck/assets/base_strip.jpg','PS 拼接底图','')}${figure(A+'scroll-workflow-deck/assets/styled_strip.jpg','风格化后的长卷','')}</div><div class="subheading">沿着长卷，看看城市</div><div id="scroll-content">${scrollStage()}</div></section>`:sub==='ecommerce'?`<section class="aigc-section"><div class="aigc-intro"><div><h2>让生成结果服务商品表达。</h2><p>电商生图尝试的展示位，按“工作流 → 示例效果 → 检查与思考”组织。当前资料未找到对应原始工作流与成图，可在此补充。</p><span class="tag">素材待补充</span></div></div><div class="subheading">First, the workflow / ComfyUI 工作流</div>${emptyAsset('commerce-workflow','电商生图工作流','上传实际 ComfyUI 节点截图；这里不以示意流程冒充已完成工作流。')}<div class="subheading">Then, the result / 示例效果</div><div class="compare"><div>${emptyAsset('commerce-before','商品原图','建议使用同一商品的原始输入。')}</div><div>${emptyAsset('commerce-after','生图效果','放入该次工作流的真实输出。')}</div></div><div class="reflection"><article><h3>商品主体是否保真</h3><p>核对形状、颜色、材质、数量与标识。背景好看不能抵消商品信息被改动。</p></article><article><h3>修改是否在允许区域</h3><p>记录用户要求和不可修改区域；尝试固定主体、生成背景，再进行合成。</p></article><article><h3>让评价可追溯</h3><p>每轮保留输入、输出、拒绝原因与修改策略。这些为下一步评测设计，不是已获得的电商效果。</p></article></div></section>`:`<section class="aigc-section"><div class="aigc-intro"><div><h2>从平面草图，探索立体表达。</h2><p>先展示目前已经跑过的轻量图生图工作流，再呈现输入与输出。工业设计手绘和真实 3D 网格的完整案例仍可继续补充。</p><span class="tag">本地测试记录</span> <span class="tag">图生图 / 3D 观感效果图</span></div></div><div class="subheading">First, the workflow / ComfyUI 工作流</div><div class="workflow-display">${figure(asset('industrial-workflow','figurine-workflow.png'),'插画转手办效果的本地工作流','现有内置节点工作流。')}<div class="workflow-text"><ol><li><b>载入输入：</b>上传简单草图，等比缩放。</li><li><b>图生图采样：</b>在原轮廓基础上加入材质、体积与光照描述。</li><li><b>检查并导出：</b>核对角色、服饰和结构变化，保存 PNG。</li></ol><a class="button small" href="assets/figurine-workflow.json" download>下载现有工作流 JSON ↓</a></div></div><div class="subheading">Then, the result / 一次真实测试</div><div class="compare"><figure><img src="${asset('industrial-before','figurine-in.png')}" alt="ComfyUI自带的简笔人物测试输入"><figcaption>测试输入：ComfyUI 自带草图，非个人工业设计作品。</figcaption></figure><figure><img src="${asset('industrial-after','figurine-out.png')}" alt="本地生成的3D手办观感效果图"><figcaption>本地实际输出：有体积和塑料光影，但服饰发生变化。</figcaption></figure></div><p class="note" style="margin-top:24px">当前输出是 PNG 效果图，不是 GLB / OBJ 模型，也不能证明结构可制造。图生图在本例中改变了服饰，后续需补身份与结构约束。可用“替换素材”放入自己的工业设计草图与实际结果。</p><div class="reflection"><article><h3>外观与几何分开验证</h3><p>“看起来立体”只是视觉表达。可旋转网格、封闭性、尺度和拓扑需要另一套验收。</p></article><article><h3>保留设计意图</h3><p>用正侧视、关键比例、材质与结构约束减少漂移，记录失败样例而非只挑最好的一张。</p></article><article><h3>降低前期表达成本</h3><p>优先用于概念沟通与方向比较；工程结构与制造可行性仍需建模和专业确认。</p></article></div></section>`;return `${breadcrumb([['设计项目','#design'],[sub==='scroll'?'风格化长卷浏览':'其他 AIGC 尝试']])}${heading('GENERATIVE EXPLORATIONS','从工作流，到视觉表达。','','Process before pixels.')}<div class="tab-bar" role="tablist" aria-label="AIGC 分类">${(sub==='scroll'?[]:[['ecommerce','电商生图'],['industrial','手绘与立体表达']]).map(([id,n])=>`<button role="tab" aria-selected="${id===sub}" data-route="aigc/${id}">${n}</button>`).join('')}</div>${body}`;}
function design(){const pdf=state.uploads.pdf;return `${breadcrumb([['设计项目','#design'],['软硬件系统设计作品集']])}${heading('DESIGN PORTFOLIO','翻开最初的设计探索。','保留完整作品集的叙事与排版，通过 PDF 直接阅读。','A book of beginnings.')}<div class="pdf-layout"><div class="pdf-book"><span>Selected Design Works</span><h2>观察。<br>思考。<br>设计。</h2>${icons.book}<small>Li Shilu / Portfolio</small></div><div class="pdf-copy"><span class="eyebrow">THE COMPLETE COLLECTION</span><h2>软硬件系统设计作品集</h2><p>创作于 2023 年保研期间。从问题观察、研究分析，到概念发展与设计表达。</p>${pdf?`<p class="file-name">▤ ${esc(pdf.name)} · ${(pdf.blob.size/1048576).toFixed(1)} MB</p><div class="actions"><a href="#pdf" class="button primary">在线阅读 PDF ↗</a><button class="button" data-upload="pdf">替换 PDF</button></div>`:`<div class="actions"><button class="button primary" data-upload="pdf">上传作品集 PDF ＋</button></div><p class="file-name">尚未放入保研作品集文件</p>`}<p id="upload-message" role="status"></p></div></div>`;}
function pdfReader(){if(!state.uploads.pdf)return design();return `${breadcrumb([['设计项目','#design'],['软硬件系统设计作品集','#design/portfolio'],['在线阅读']])}<div class="reader-toolbar"><span class="file-name">${esc(state.uploads.pdf.name)}</span><div class="actions"><a class="button small" href="${state.urls.pdf}" target="_blank" rel="noopener">独立窗口打开 ↗</a><a class="button small" href="${state.urls.pdf}" download="${esc(state.uploads.pdf.name)}">下载 PDF ↓</a></div></div><section class="pdf-viewer" aria-label="PDF 在线阅读器"><div class="pdf-controls"><button class="button small" id="pdf-prev" data-pdf="prev" disabled>← 上一页</button><span id="pdf-page-count" aria-live="polite">正在加载 PDF…</span><button class="button small" id="pdf-next" data-pdf="next" disabled>下一页 →</button><button class="button small" data-pdf="minus" aria-label="缩小PDF">−</button><button class="button small" data-pdf="plus" aria-label="放大PDF">＋</button></div><div id="pdf-canvas-wrap"><canvas id="pdf-canvas" aria-label="PDF 当前页"></canvas></div><p id="pdf-read-status" role="status"></p></section><p class="note">文件在浏览器本地解析。也可使用“独立窗口打开”或下载阅读。</p>`;}
function notFound(){return `<div class="not-found"><span class="eyebrow">THIS PAGE IS STILL A BLANK SHEET</span><h1>这页手记还没有写下。</h1><p>回到目录，翻开另一页。</p><a class="button" href="#home">返回首页 →</a></div>`;}
function route(keepScroll=false){const parts=(location.hash.slice(1)||'home').split('/');const top=parts[0];const y=scrollY;const views={home,internships,vibe,aigc:()=>aigc(parts[1]),project:()=>project(parts[1]),design:()=>parts[1]==='portfolio'?design():designHub(),pdf:pdfReader};main.innerHTML=(views[top]||notFound)();main.className='page-enter';if(top==='pdf'&&state.uploads.pdf)loadPDF();let active=top==='project'?'vibe':['pdf','aigc'].includes(top)?'design':top;document.querySelectorAll('[data-nav]').forEach(n=>{n.removeAttribute('aria-current');if(n.dataset.nav===active){n.setAttribute('aria-current','page');if(innerWidth<850)n.scrollIntoView({block:'nearest',inline:'center',behavior:'instant'});}});const names={home:'Shilu · 我的分身',internships:'产品实习',vibe:'AI 项目',aigc:'设计项目 · AIGC',design:parts[1]==='portfolio'?'软硬件系统设计作品集':'设计项目',pdf:'PDF 在线阅读',project:PROJECTS[parts[1]]?.name||'项目'};document.title=(names[top]||'页面未找到')+(top==='home'?'':' · 李诗璐');if(!keepScroll){window.scrollTo({top:0,behavior:'instant'});}else window.scrollTo(0,y);window.portfolioDraft?.render();}
const slots=[['portrait','首页个人照片','image'],['scroll-workflow','长卷工作流截图','image'],['scroll-zju','浙大长卷成图','image'],['scroll-xihu','西湖长卷成图','image'],['scroll-ningbo','宁波长卷成图','image'],['commerce-workflow','电商生图工作流','image'],['commerce-before','电商商品原图','image'],['commerce-after','电商生成效果','image'],['industrial-workflow','手绘 / 立体表达工作流','image'],['industrial-before','个人手绘输入','image'],['industrial-after','立体表达结果','image'],['pdf','保研作品集 PDF','pdf']];
let dbPromise;
function db(){return dbPromise??=new Promise((resolve,reject)=>{const request=indexedDB.open('shilu-portfolio',1);request.onupgradeneeded=()=>request.result.createObjectStore('assets');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function stored(mode,key,value){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('assets',mode);const st=tx.objectStore('assets');let request=value===undefined?st.get(key):value===null?st.delete(key):st.put(value,key);let result;request.onsuccess=()=>result=request.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
function installAsset(key,item){if(state.urls[key])URL.revokeObjectURL(state.urls[key]);if(item){state.uploads[key]=item;state.urls[key]=URL.createObjectURL(item.blob);}else{delete state.uploads[key];delete state.urls[key];}}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),4500);}
async function upload(key,file){if(!file)return;try{const type=slots.find(x=>x[0]===key)?.[2];if(type==='pdf'){if(file.size>50*1024*1024)throw Error('PDF 超过 50 MB，请压缩后重试。');const head=new TextDecoder().decode(await file.slice(0,5).arrayBuffer());if(head!=='%PDF-')throw Error('文件不是有效的 PDF，请重新选择。');}else{if(file.size>15*1024*1024)throw Error('图片超过 15 MB，请压缩后重试。');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('请选择 JPG、PNG 或 WebP 图片。');await createImageBitmap(file).then(b=>b.close());}const item={name:file.name,blob:file,type:file.type,date:new Date().toISOString()};await stored('readwrite',key,item);installAsset(key,item);renderEditor();route(true);toast('已保存到当前浏览器，可立即预览。');}catch(e){toast(e.message||'保存失败，请检查浏览器存储空间后重试。');const el=document.querySelector('#editor-status');el.textContent=e.message||'保存失败';}}
function filePicker(key){const input=document.createElement('input');input.type='file';input.accept=key==='pdf'?'application/pdf':'.png,.jpg,.jpeg,.webp';input.style.display='none';document.body.appendChild(input);input.onchange=async()=>{await upload(key,input.files[0]);input.remove();};input.addEventListener('cancel',()=>input.remove(),{once:true});input.click();}
function renderEditor(){document.querySelector('#editor-fields').innerHTML=slots.map(([id,name,type])=>`<div class="editor-row"><label for="file-${id}">${name}</label><input id="file-${id}" data-file="${id}" type="file" accept="${type==='pdf'?'application/pdf':'.png,.jpg,.jpeg,.webp'}"><small>${state.uploads[id]?esc(state.uploads[id].name):type==='pdf'?'尚未上传 PDF':'保留默认素材或待补充位置'}</small>${state.uploads[id]?`<button data-reset="${id}">移除本次上传，恢复默认</button>`:''}</div>`).join('');}
function openEditor(){renderEditor();document.querySelector('#editor-status').textContent='';document.querySelector('#editor').showModal();}
document.querySelector('#open-editor').onclick=openEditor;document.querySelector('#footer-editor').onclick=openEditor;
document.addEventListener('click',async e=>{if(e.target.closest('.skip')){e.preventDefault();main.focus();main.scrollIntoView({behavior:'instant'});return;}const close=e.target.closest('[data-close]');if(close){document.getElementById(close.dataset.close).close();return;}const image=e.target.closest('[data-image]');if(image){document.querySelector('#lightbox-image').src=image.dataset.image;document.querySelector('#lightbox-image').alt=image.dataset.title;document.querySelector('#lightbox-title').textContent=image.dataset.title;document.querySelector('#lightbox').showModal();return;}const go=e.target.closest('[data-route]');if(go){location.hash=go.dataset.route;return;}const jump=e.target.closest('[data-jump]');if(jump){e.preventDefault();document.getElementById(jump.dataset.jump)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}const s=e.target.closest('[data-scroll]');if(s){state.scroll=s.dataset.scroll;document.querySelector('#scroll-content').innerHTML=scrollStage();window.portfolioDraft?.render();return;}const up=e.target.closest('[data-upload]');if(up){filePicker(up.dataset.upload);return;}const reset=e.target.closest('[data-reset]');if(reset){try{await stored('readwrite',reset.dataset.reset,null);installAsset(reset.dataset.reset,null);renderEditor();route(true);toast('已恢复默认素材。');}catch{toast('移除失败，请重试。');}}});
document.addEventListener('change',e=>{if(e.target.dataset.file)upload(e.target.dataset.file,e.target.files[0]);});
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
window.addEventListener('hashchange',()=>{route();main.focus({preventScroll:true});});
route();
(async()=>{try{for(const[id]of slots){const item=await stored('readonly',id);if(item?.blob)installAsset(id,item);}route(true);}catch{toast('浏览器存储不可用，已有作品仍可浏览。');}})();
let pdfTask=0,pdfDoc=null,pdfPage=1,pdfZoom=1,pdfRendering=false;
async function loadPDF(){const ticket=++pdfTask;pdfDoc=null;pdfPage=1;pdfZoom=1;try{const lib=await import('./assets/pdfjs/pdf.min.mjs');lib.GlobalWorkerOptions.workerSrc=new URL('./assets/pdfjs/pdf.worker.min.mjs',location.href).href;const data=await state.uploads.pdf.blob.arrayBuffer();const doc=await lib.getDocument({data,isEvalSupported:false,enableXfa:false}).promise;if(ticket!==pdfTask||!document.getElementById('pdf-canvas'))return;pdfDoc=doc;await drawPDF();}catch(e){const el=document.getElementById('pdf-read-status');if(el)el.textContent='当前文件无法在内嵌阅读器解析，请使用独立窗口打开，或更换未加密的PDF。';const c=document.getElementById('pdf-page-count');if(c)c.textContent='预览不可用';}}
async function drawPDF(){if(!pdfDoc||pdfRendering)return;pdfRendering=true;const canvas=document.getElementById('pdf-canvas');if(!canvas){pdfRendering=false;return;}const prev=document.getElementById('pdf-prev'),next=document.getElementById('pdf-next');prev.disabled=true;next.disabled=true;try{const page=await pdfDoc.getPage(pdfPage);const base=page.getViewport({scale:1});const fit=Math.min(1150,document.getElementById('pdf-canvas-wrap').clientWidth-32)/base.width;const ratio=Math.min(devicePixelRatio||1,2);const view=page.getViewport({scale:fit*pdfZoom});canvas.width=Math.floor(view.width*ratio);canvas.height=Math.floor(view.height*ratio);canvas.style.width=view.width+'px';canvas.style.height=view.height+'px';await page.render({canvasContext:canvas.getContext('2d'),viewport:view,transform:[ratio,0,0,ratio,0,0]}).promise;document.getElementById('pdf-page-count').textContent=pdfPage+' / '+pdfDoc.numPages+' 页';document.getElementById('pdf-read-status').textContent='';}catch{const el=document.getElementById('pdf-read-status');if(el)el.textContent='当前页渲染失败，可以下载PDF后阅读。';}finally{pdfRendering=false;if(document.contains(prev)){prev.disabled=pdfPage<=1;next.disabled=pdfPage>=pdfDoc.numPages;}}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-pdf]');if(!b||!pdfDoc||pdfRendering)return;const action=b.dataset.pdf;if(action==='prev'&&pdfPage>1)pdfPage--;if(action==='next'&&pdfPage<pdfDoc.numPages)pdfPage++;if(action==='minus')pdfZoom=Math.max(.5,pdfZoom-.25);if(action==='plus')pdfZoom=Math.min(3,pdfZoom+.25);await drawPDF();});
